const KEYS = ['group', 'product', 'store', 'category', 'price', 'was', 'url', 'src', 'signal', 'evidence', 'terms'];
const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, '');

export const deals = raw.map((row) => {
  const d = Object.fromEntries(KEYS.map((k, i) => [k, row[i]]));
  const id = `${d.group}-${slug(d.store)}`;
  const src = SOURCES[d.src];
  const page = STORE_PAGE_READS[id];
  const checked = page ? page.at : src.read;
  return {
    ...d,
    id,
    terms: d.terms ?? '',
    note: CARD_NOTES[id],
    reads: [...(EARLIER_READS[id] ?? []).map(([at, price]) => ({ at, price })), { at: checked, price: d.price }],
    source: src.name,
    site: src.name.split(' ').slice(0, 2).join(' '), // the publication ("NBC Select"), for the card's one line
    sourceTitle: src.title,
    sourceUrl: src.url,
    sourceUpdated: src.updated,
    readAt: page ? 'store page' : `deals source: ${src.name}`,
    checked,
  };
});
